
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_22_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_22", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.247993119361522e+00, -5.145821748754233e+00, -5.002448359836666e+00, -4.803357692573510e+00, -4.530891969820581e+00, -4.165220676190341e+00, -3.686270543293043e+00, -3.074993171352338e+00, -2.315160436131765e+00, -1.462419436408368e+00, -8.198951307298560e-01, -6.110774215366661e-01, -6.353267949029275e-01, -5.486176467640244e-01, -3.615963822509096e-01, -1.829844285034567e-01, -7.522479657155984e-02, -2.442318086997303e-02, -5.223810811767026e-03, -5.873265056353274e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


